INSERT INTO quizzes (slug, kind, title, blurb, opens_at, seconds_per_question) VALUES ('weekly-2026-10-31', 'weekly', 'শনিবারের কুইজ · ৩১ অক্টোবর', 'ত্বক থেকে বজ্রপাত, চাঁদ থেকে খাবার স্যালাইন — ৫টি প্রশ্ন, প্রতিটায় ২০ সেকেন্ড।', '2026-10-31 14:00:00', 20) ON DUPLICATE KEY UPDATE kind=VALUES(kind), title=VALUES(title), blurb=VALUES(blurb), opens_at=VALUES(opens_at), seconds_per_question=VALUES(seconds_per_question);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('w1031-1', 'weekly-2026-10-31', 0, 'মানুষের শরীরে সবচেয়ে বড় অঙ্গ কোনটি?', 'যকৃৎ', 'ত্বক', 'ফুসফুস', 'মস্তিষ্ক', 1, 'ত্বক! পুরো শরীর মুড়ে রাখা এই অঙ্গ আমাদের জীবাণু, রোদ আর পানি হারানো থেকে বাঁচায়। শরীরের ভেতরের অঙ্গগুলোর মধ্যে সবচেয়ে বড় যকৃৎ।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('w1031-2', 'weekly-2026-10-31', 1, 'বজ্রপাতের সময় কোন জায়গাটা সবচেয়ে নিরাপদ?', 'বড় গাছের নিচে', 'খোলা মাঠে শুয়ে থাকা', 'পাকা দালানের ভেতরে', 'পুকুরে নেমে যাওয়া', 2, 'পাকা দালান বা ধাতব ছাদওয়ালা বন্ধ গাড়ি সবচেয়ে নিরাপদ। গাছের নিচে দাঁড়ালে বিপদ উল্টো বাড়ে।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('w1031-3', 'weekly-2026-10-31', 2, 'পেঁয়াজ কাটলে চোখে পানি আসে কেন?', 'কাটার সময় একটা উদ্বায়ী গ্যাস তৈরি হয় বলে', 'পেঁয়াজের রস ছিটে চোখে পড়ে বলে', 'পেঁয়াজের গন্ধে মন খারাপ হয় বলে', 'ছুরির ধাতুর কারণে', 0, 'কোষ ভাঙলে বিক্রিয়ায় সিন-প্রোপানেথিয়াল-এস-অক্সাইড তৈরি হয়, যা চোখের স্নায়ুকে জ্বালায়। চোখ তখন পানি দিয়ে সেটা ধুয়ে ফেলতে চায়।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('w1031-4', 'weekly-2026-10-31', 3, 'ডায়রিয়ায় পানিশূন্যতা ঠেকাতে সবচেয়ে কার্যকর কোনটি?', 'ডাবের পানি', 'কোমল পানীয়', 'শুধু সাদা পানি', 'খাবার স্যালাইন', 3, 'খাবার স্যালাইনে লবণ আর গ্লুকোজ মাপা অনুপাতে থাকে, তাই অন্ত্র দ্রুত পানি শুষে নেয়। এর কার্যকারিতা প্রমাণে ঢাকার আইসিডিডিআর,বি-র বড় ভূমিকা আছে।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('w1031-5', 'weekly-2026-10-31', 4, 'চাঁদ নিজের অক্ষে একবার ঘুরতে মোটামুটি কত দিন নেয়?', '১ দিন', 'প্রায় ২৭ দিন', '৭ দিন', '৩৬৫ দিন', 1, 'প্রায় ২৭ দিন — পৃথিবীকে একবার ঘুরে আসতেও ঠিক ততদিন লাগে। তাই চাঁদের একই মুখ সবসময় আমাদের দিকে থাকে।', NULL, NULL, NULL);
INSERT INTO quizzes (slug, kind, title, blurb, opens_at, seconds_per_question) VALUES ('weekly-2026-11-07', 'weekly', 'শনিবারের কুইজ · ৭ নভেম্বর', 'নীল আকাশ, প্রবাল দ্বীপ আর হলুদের রং-বদল — ৫টি প্রশ্ন, প্রতিটায় ২০ সেকেন্ড।', '2026-11-07 14:00:00', 20) ON DUPLICATE KEY UPDATE kind=VALUES(kind), title=VALUES(title), blurb=VALUES(blurb), opens_at=VALUES(opens_at), seconds_per_question=VALUES(seconds_per_question);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('w1107-1', 'weekly-2026-11-07', 0, 'আকাশ নীল দেখায় কেন?', 'সাগরের পানির প্রতিফলনে', 'বাতাসের কণা নীল আলো বেশি ছড়িয়ে দেয় বলে', 'ওজোন স্তর নীল রঙের বলে', 'সূর্যের আলো নীল বলে', 1, 'সূর্যের সাদা আলোর মধ্যে নীল আলো বাতাসের কণায় লেগে সবচেয়ে বেশি চারদিকে ছিটকে যায়। তাই যেদিকেই তাকাও, আকাশ নীল।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('w1107-2', 'weekly-2026-11-07', 1, 'বাংলাদেশের একমাত্র প্রবাল দ্বীপ কোনটি?', 'ভোলা', 'হাতিয়া', 'কুতুবদিয়া', 'সেন্টমার্টিন', 3, 'সেন্টমার্টিনের চারপাশে প্রবাল আর নানা সামুদ্রিক প্রাণী থাকে। প্রবাল খুব ধীরে বাড়ে, তাই এই দ্বীপ রক্ষা করা খুব জরুরি।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('w1107-3', 'weekly-2026-11-07', 2, 'হলুদের দাগে সাবান লাগালে দাগটা কোন রঙের হয়ে যায়?', 'লালচে', 'নীল', 'সবুজ', 'সাদা', 0, 'হলুদের কারকিউমিন (curcumin) ক্ষারের সংস্পর্শে লালচে হয়ে যায়, আর সাবান ক্ষারীয়। রান্নাঘরেই একটা প্রাকৃতিক নির্দেশক!', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('w1107-4', 'weekly-2026-11-07', 3, 'কোন ভিটামিনের অভাবে রাতকানা রোগ হয়?', 'ভিটামিন সি', 'ভিটামিন ডি', 'ভিটামিন এ', 'ভিটামিন কে', 2, 'ভিটামিন এ চোখের আলো-সংবেদী কোষের জন্য জরুরি। কলিজা, ডিম, মলা মাছ আর গাজর-মিষ্টিকুমড়া-শাকের মতো খাবার এর ভালো উৎস।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('w1107-5', 'weekly-2026-11-07', 4, 'বিদ্যুৎ চমকানোর কত সেকেন্ড পর গর্জন শুনলে বজ্রপাত প্রায় ১ কিলোমিটার দূরে?', 'প্রায় ১ সেকেন্ড', 'প্রায় ৩ সেকেন্ড', 'প্রায় ১০ সেকেন্ড', 'প্রায় ৩০ সেকেন্ড', 1, 'শব্দ বাতাসে সেকেন্ডে প্রায় ৩৪৩ মিটার যায়, তাই ৩ সেকেন্ডে প্রায় ১ কিলোমিটার। আলো প্রায় সাথে সাথেই পৌঁছে যায়।', NULL, NULL, NULL);
INSERT INTO quizzes (slug, kind, title, blurb, opens_at, seconds_per_question) VALUES ('weekly-2026-11-14', 'weekly', 'শনিবারের কুইজ · ১৪ নভেম্বর', 'গাছের সাড়া, হেঁচকি, শুক্রের লম্বা দিন — ৫টি প্রশ্ন, প্রতিটায় ২০ সেকেন্ড।', '2026-11-14 14:00:00', 20) ON DUPLICATE KEY UPDATE kind=VALUES(kind), title=VALUES(title), blurb=VALUES(blurb), opens_at=VALUES(opens_at), seconds_per_question=VALUES(seconds_per_question);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('w1114-1', 'weekly-2026-11-14', 0, 'জগদীশচন্দ্র বসু কোন যন্ত্র দিয়ে গাছের বৃদ্ধি মাপতেন?', 'ক্রেস্কোগ্রাফ', 'থার্মোমিটার', 'ব্যারোমিটার', 'সিসমোগ্রাফ', 0, 'ক্রেস্কোগ্রাফ (crescograph) গাছের খুব সামান্য বৃদ্ধিকেও অনেক গুণ বড় করে দেখাতে পারত। এ দিয়েই তিনি দেখান, গাছও আঘাত আর তাপে সাড়া দেয়।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('w1114-2', 'weekly-2026-11-14', 1, 'হেঁচকির সময় শরীরের কোন পেশিতে হঠাৎ টান পড়ে?', 'পাকস্থলী', 'মধ্যচ্ছদা (ডায়াফ্রাম)', 'হৃৎপিণ্ড', 'জিভ', 1, 'বুক আর পেটের মাঝের পেশি মধ্যচ্ছদা হঠাৎ সংকুচিত হলে বাতাস ঢোকে, আর স্বরযন্ত্রের মুখ ঝট করে বন্ধ হয়ে ‘হিক’ শব্দ হয়।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('w1114-3', 'weekly-2026-11-14', 2, 'কোন গ্রহে একদিন তার এক বছরের চেয়েও লম্বা?', 'মঙ্গল', 'বৃহস্পতি', 'শুক্র', 'শনি', 2, 'শুক্র নিজের অক্ষে এত ধীরে ঘোরে যে একবার ঘুরতে লাগে পৃথিবীর প্রায় ২৪৩ দিন — অথচ সূর্যকে ঘুরে আসে প্রায় ২২৫ দিনে।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('w1114-4', 'weekly-2026-11-14', 3, 'শিকাগোর বিখ্যাত সিয়ার্স টাওয়ারের কাঠামো-নকশার পেছনে বাংলাদেশে জন্ম নেওয়া কোন প্রকৌশলী?', 'জামাল নজরুল ইসলাম', 'কাজী আজিজুল হক', 'জগদীশচন্দ্র বসু', 'ফজলুর রহমান খান', 3, 'ফজলুর রহমান খান উঁচু ভবনের জন্য ‘টিউব’ কাঠামোর ধারণা দেন, যা কম খরচে আকাশছোঁয়া ভবন বানানো সহজ করে। সিয়ার্স টাওয়ারের নাম এখন উইলিস টাওয়ার।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('w1114-5', 'weekly-2026-11-14', 4, 'পানি জমে বরফ হলে তার আয়তনের কী হয়?', 'কমে যায়', 'বেড়ে যায়', 'একই থাকে', 'অর্ধেক হয়ে যায়', 1, 'জমার সময় পানির অণুগুলো ফাঁকা ফাঁকা কাঠামো বানায়, তাই বরফ পানির চেয়ে হালকা — আর পানিতে ভাসে।', NULL, NULL, NULL);
INSERT INTO quizzes (slug, kind, title, blurb, opens_at, seconds_per_question) VALUES ('weekly-2026-11-21', 'weekly', 'শনিবারের কুইজ · ২১ নভেম্বর', 'সুন্দরবন, প্রেশার কুকার আর বঙ্গোপসাগরের তিমি — ৫টি প্রশ্ন, প্রতিটায় ২০ সেকেন্ড।', '2026-11-21 14:00:00', 20) ON DUPLICATE KEY UPDATE kind=VALUES(kind), title=VALUES(title), blurb=VALUES(blurb), opens_at=VALUES(opens_at), seconds_per_question=VALUES(seconds_per_question);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('w1121-1', 'weekly-2026-11-21', 0, 'সুন্দরবন কী ধরনের বন?', 'চিরসবুজ পাহাড়ি বন', 'ম্যানগ্রোভ বা শ্বাসমূলীয় বন', 'পাতাঝরা শালবন', 'মরুভূমির ঝোপবন', 1, 'সুন্দরবন পৃথিবীর সবচেয়ে বড় ম্যানগ্রোভ বন। এখানকার অনেক গাছের শ্বাসমূল কাদা ফুঁড়ে ওপরে উঠে বাতাস থেকে শ্বাস নেয়।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('w1121-2', 'weekly-2026-11-21', 1, 'আঙুলের ছাপ নিয়ে কোনটি সত্য?', 'বয়স বাড়লে ছাপ পুরো বদলে যায়', 'ভাই-বোনের ছাপ হুবহু এক হয়', 'অভিন্ন যমজদেরও ছাপ আলাদা', 'শুধু বড়দের আঙুলে ছাপ থাকে', 2, 'অভিন্ন যমজের ডিএনএ প্রায় এক হলেও আঙুলের ছাপ আলাদা — গর্ভে থাকার সময়ের ছোট ছোট পার্থক্য রেখার নকশা বদলে দেয়।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('w1121-3', 'weekly-2026-11-21', 2, 'প্রেশার কুকারে রান্না দ্রুত হয় কেন?', 'চাপ বাড়লে পানি বেশি তাপমাত্রায় ফোটে', 'ঢাকনা থাকায় আলো ঢোকে না', 'কুকারের ধাতু খাবারকে নরম করে', 'বাষ্প খাবারের স্বাদ বাড়ায়', 0, 'খোলা হাঁড়িতে পানি ১০০° সেলসিয়াসে ফোটে, কিন্তু প্রেশার কুকারে চাপ বেশি থাকায় তাপমাত্রা প্রায় ১২০° পর্যন্ত ওঠে — তাই খাবার তাড়াতাড়ি সেদ্ধ হয়।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('w1121-4', 'weekly-2026-11-21', 3, 'রক্তের কোন কণিকা শরীরে অক্সিজেন বয়ে নেয়?', 'শ্বেত রক্তকণিকা', 'অণুচক্রিকা', 'প্লাজমা', 'লোহিত রক্তকণিকা', 3, 'লোহিত রক্তকণিকার হিমোগ্লোবিন (hemoglobin) অক্সিজেন ধরে রাখে। এতে আয়রন আছে, আর সেজন্যই রক্ত লাল।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('w1121-5', 'weekly-2026-11-21', 4, 'তিমি কোন শ্রেণির প্রাণী?', 'মাছ', 'স্তন্যপায়ী', 'সরীসৃপ', 'উভচর', 1, 'তিমি ফুসফুস দিয়ে শ্বাস নেয় আর বাচ্চাকে দুধ খাওয়ায় — তাই সে মাছ নয়, স্তন্যপায়ী। বঙ্গোপসাগরের ‘সোয়াচ অব নো গ্রাউন্ড’ এলাকাতেও তিমি দেখা যায়।', NULL, NULL, NULL);
INSERT INTO quizzes (slug, kind, title, blurb, opens_at, seconds_per_question) VALUES ('ep-mosha', 'episode', 'পর্বের কুইজ: মশা কেন আমাকেই কামড়ায়?', 'পর্বটা দেখেছ? তিন প্রশ্নে যাচাই করো ভাবুর মশা-গবেষণা কতটা মনে আছে।', NULL, 20) ON DUPLICATE KEY UPDATE kind=VALUES(kind), title=VALUES(title), blurb=VALUES(blurb), opens_at=VALUES(opens_at), seconds_per_question=VALUES(seconds_per_question);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('ep-mosha-1', 'ep-mosha', 0, 'কোন মশা মানুষকে কামড়ায়?', 'শুধু পুরুষ মশা', 'শুধু স্ত্রী মশা', 'দুটোই সমানভাবে', 'শুধু বাচ্চা মশা', 1, 'শুধু স্ত্রী মশা রক্ত খায় — ডিম তৈরির প্রোটিনের জন্য। পুরুষ মশা সারাজীবন ফুলের রস খায়।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('ep-mosha-2', 'ep-mosha', 1, 'মশা আমাদের খুঁজে পায় কী দিয়ে?', 'আমাদের কথা শুনে', 'আমাদের ছায়া দেখে', 'ঘামের গন্ধ আর নিঃশ্বাসের কার্বন ডাই-অক্সাইড টের পেয়ে', 'আমাদের চুলের রং দেখে', 2, 'আমরা যে কার্বন ডাই-অক্সাইড (CO₂) ছাড়ি, মশা তা দূর থেকেই টের পায়। কাছে এলে ঘামের গন্ধ তাকে ঠিক জায়গায় নিয়ে আসে।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('ep-mosha-3', 'ep-mosha', 2, 'কোন রঙের কাপড় মশাকে বেশি টানে?', 'গাঢ় রং', 'সাদা', 'হালকা সবুজ', 'হালকা ঘিয়ে', 0, 'গাঢ় রঙের কাপড় মশার চোখে সহজে ধরা পড়ে। মশার মৌসুমে হালকা রঙের ঢিলেঢালা পোশাক একটু হলেও সাহায্য করে।', NULL, NULL, NULL);
INSERT INTO quizzes (slug, kind, title, blurb, opens_at, seconds_per_question) VALUES ('ep-bang', 'episode', 'পর্বের কুইজ: ব্যাঙ কেন ডাকে?', 'বর্ষার রাতের ঘ্যাঙর-ঘ্যাং নিয়ে তিনটি প্রশ্ন। দেখো তো রাফির চেয়ে বেশি পারো কি না!', NULL, 20) ON DUPLICATE KEY UPDATE kind=VALUES(kind), title=VALUES(title), blurb=VALUES(blurb), opens_at=VALUES(opens_at), seconds_per_question=VALUES(seconds_per_question);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('ep-bang-1', 'ep-bang', 0, 'বর্ষায় যে ব্যাঙের ডাক শুনি, সেটা মূলত কারা ডাকে?', 'স্ত্রী ব্যাঙ', 'পুরুষ ব্যাঙ', 'ব্যাঙাচি', 'সব ব্যাঙ সমানভাবে', 1, 'ডাকে মূলত পুরুষ ব্যাঙ — সঙ্গী খুঁজতে। স্ত্রী ব্যাঙ ডাক শুনে পছন্দের সঙ্গীর কাছে যায়।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('ep-bang-2', 'ep-bang', 1, 'ব্যাঙের ডাক এত জোরে শোনায় কেন?', 'ব্যাঙের গলা খুব লম্বা বলে', 'পানিতে শব্দ বেড়ে যায় বলে', 'গলার স্বরথলি ফুলে শব্দকে জোরালো করে বলে', 'ব্যাঙ একসাথে অনেকবার মুখ খোলে বলে', 2, 'ডাকার সময় ব্যাঙের গলার পাতলা থলি — স্বরথলি (vocal sac) — বেলুনের মতো ফোলে। এই থলি শব্দকে জোরালো করে অনেক দূর পৌঁছে দেয়।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('ep-bang-3', 'ep-bang', 2, 'বৃষ্টির পর ব্যাঙ বেশি ডাকে কেন?', 'বর্ষা তাদের প্রজননের মৌসুম', 'বৃষ্টিতে তাদের ঠান্ডা লাগে', 'বজ্রপাতে ভয় পায়', 'বৃষ্টির শব্দ ঢাকতে', 0, 'বর্ষায় ডোবা-নালা পানিতে ভরে, ডিম পাড়ার জায়গা মেলে। তাই এ সময়টাই ব্যাঙের প্রজননকাল — আর ডাকাডাকিও তখন সবচেয়ে বেশি।', NULL, NULL, NULL);
INSERT INTO quizzes (slug, kind, title, blurb, opens_at, seconds_per_question) VALUES ('ep-mati-gondho', 'episode', 'পর্বের কুইজ: বৃষ্টির পরে মাটির গন্ধ', 'সোঁদা গন্ধের রসায়ন মনে আছে? তিন প্রশ্নে পরীক্ষা হয়ে যাক।', NULL, 20) ON DUPLICATE KEY UPDATE kind=VALUES(kind), title=VALUES(title), blurb=VALUES(blurb), opens_at=VALUES(opens_at), seconds_per_question=VALUES(seconds_per_question);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('ep-mati-1', 'ep-mati-gondho', 0, 'বৃষ্টির পর মাটির সোঁদা গন্ধের বৈজ্ঞানিক নাম কী?', 'সালোকসংশ্লেষণ', 'পেট্রিকর', 'জারণ', 'বাষ্পীভবন', 1, '‘পেট্রিকর’ (petrichor) নামটা দিয়েছিলেন দুই অস্ট্রেলীয় বিজ্ঞানী, ১৯৬৪ সালে। গ্রিক ভাষায় ‘পেট্রা’ মানে পাথর।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('ep-mati-2', 'ep-mati-gondho', 1, 'গন্ধের মূল উপাদান জিওসমিন কারা তৈরি করে?', 'মেঘের পানি', 'গাছের পাতা', 'কেঁচো', 'মাটির কিছু ব্যাকটেরিয়া', 3, 'মাটিতে থাকা কিছু ব্যাকটেরিয়া, বিশেষ করে স্ট্রেপটোমাইসিস (Streptomyces), জিওসমিন (geosmin) তৈরি করে। বৃষ্টির ফোঁটা মাটিতে পড়লে তা বাতাসে ছড়িয়ে যায়।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('ep-mati-3', 'ep-mati-gondho', 2, 'মানুষের নাক জিওসমিন কতটা টের পায়?', 'অনেক বেশি পরিমাণ হলে তবেই', 'একেবারেই টের পায় না', 'খুব সামান্য পরিমাণও টের পায়', 'শুধু রাতে টের পায়', 2, 'জিওসমিনের ব্যাপারে মানুষের নাক অসম্ভব সংবেদনশীল — বাতাসে এর অতি সামান্য উপস্থিতিও আমরা টের পাই। এজন্যই বৃষ্টির প্রথম গন্ধটা এত স্পষ্ট লাগে।', NULL, NULL, NULL);
INSERT INTO quizzes (slug, kind, title, blurb, opens_at, seconds_per_question) VALUES ('ep-jonaki', 'episode', 'পর্বের কুইজ: জোনাকি কেন জ্বলে?', 'অন্ধকারে টিমটিম আলোর রহস্য — তিন প্রশ্নে ঝালিয়ে নাও।', NULL, 20) ON DUPLICATE KEY UPDATE kind=VALUES(kind), title=VALUES(title), blurb=VALUES(blurb), opens_at=VALUES(opens_at), seconds_per_question=VALUES(seconds_per_question);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('ep-jonaki-1', 'ep-jonaki', 0, 'জোনাকির আলো তৈরি হয় কীভাবে?', 'শরীরের ভেতরের রাসায়নিক বিক্রিয়ায়', 'ছোট্ট ব্যাটারি থেকে', 'দিনের রোদ জমিয়ে রেখে', 'বাতাসের ঘষায়', 0, 'জোনাকির শরীরে লুসিফেরিন (luciferin) নামের পদার্থ লুসিফারেজ (luciferase) এনজাইমের সাহায্যে অক্সিজেনের সাথে বিক্রিয়া করে আলো দেয়।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('ep-jonaki-2', 'ep-jonaki', 1, 'জোনাকির আলোকে ‘ঠান্ডা আলো’ বলা হয় কেন?', 'রাতে জ্বলে বলে', 'এতে প্রায় কোনো তাপ তৈরি হয় না বলে', 'নীল রঙের বলে', 'শীতকালে জ্বলে বলে', 1, 'সাধারণ বাল্বের অনেক শক্তি তাপ হয়ে নষ্ট হয়, কিন্তু জোনাকির বিক্রিয়ার প্রায় পুরো শক্তিই আলো হয়। তাই জোনাকির আলো গরম নয়।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('ep-jonaki-3', 'ep-jonaki', 2, 'জোনাকি জ্বলে-নেভে কেন?', 'ক্লান্ত হয়ে যায় বলে', 'বাতাসে আলো নিভে যায় বলে', 'চোখ পিটপিট করার অভ্যাসে', 'নির্দিষ্ট ছন্দে সঙ্গীকে সংকেত পাঠাতে', 3, 'প্রতিটি প্রজাতির জোনাকির আলোর নিজস্ব ছন্দ আছে। এই ছন্দ দেখেই একই প্রজাতির সঙ্গী একে অন্যকে চিনে নেয়।', NULL, NULL, NULL);
INSERT INTO quizzes (slug, kind, title, blurb, opens_at, seconds_per_question) VALUES ('series-rannaghar', 'initiator', 'নাদিয়ার কুইজ: রান্নাঘরের বিজ্ঞান', 'ভাত, দুধ, চা আর পেঁয়াজ — নাদিয়ার সিরিজ থেকে ৫টি প্রশ্ন। রান্নাঘরের রসায়ন কতটা জানো?', NULL, 20) ON DUPLICATE KEY UPDATE kind=VALUES(kind), title=VALUES(title), blurb=VALUES(blurb), opens_at=VALUES(opens_at), seconds_per_question=VALUES(seconds_per_question);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('init-rannaghar-1', 'series-rannaghar', 0, 'ভাত রান্না করলে ফুলে ওঠে কেন?', 'চালের শ্বেতসার পানি শুষে ফুলে যায়', 'চালে বাতাস ঢোকে', 'চাল গলে গিয়ে আবার জমে', 'হাঁড়ির চাপে বড় হয়', 0, 'গরম পানিতে চালের শ্বেতসার (starch) দানা পানি টেনে ফুলে ওঠে আর নরম হয় — একে বলে জেলাটিনাইজেশন (gelatinization)।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('init-rannaghar-2', 'series-rannaghar', 1, 'দুধ গরম করলে উথলে ওঠে কেন?', 'দুধে গ্যাস মেশানো থাকে', 'দুধ পানির চেয়ে হালকা', 'ওপরে সর জমে বাষ্প আটকে ফেলে', 'দুধের চিনি ফুটে ওঠে', 2, 'গরমে দুধের প্রোটিন আর চর্বি মিলে ওপরে সরের পাতলা স্তর তৈরি হয়। নিচের বাষ্প সেটা ঠেলে বেরোতে গিয়ে ফেনা হয়ে উথলে পড়ে।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('init-rannaghar-3', 'series-rannaghar', 2, 'লাল বাঁধাকপির রস দিয়ে কী বোঝা যায়?', 'খাবারে কত ক্যালরি', 'কোনো তরল অম্লীয় না ক্ষারীয়', 'পানিতে কত লবণ', 'তেলে ভেজাল আছে কি না', 1, 'লাল বাঁধাকপির অ্যান্থোসায়ানিন (anthocyanin) অম্লে লালচে-গোলাপি আর ক্ষারে সবুজাভ-নীল হয়ে যায়। রান্নাঘরেই তৈরি পিএইচ নির্দেশক!', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('init-rannaghar-4', 'series-rannaghar', 3, 'লাল চায়ে লেবু দিলে রং হালকা হয়ে যায় কেন?', 'লেবু চায়ের পাতা গলিয়ে দেয়', 'লেবুর রস চা পাতলা করে', 'লেবুর রং চায়ে মেশে', 'লেবুর অ্যাসিড চায়ের রঞ্জকের রং বদলে দেয়', 3, 'চায়ের লালচে-বাদামি রং আসে কিছু রঞ্জক থেকে, যাদের রং অম্ল-ক্ষারের ওপর নির্ভর করে। লেবুর অ্যাসিড পড়লে রং হালকা হয়ে যায়।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('init-rannaghar-5', 'series-rannaghar', 4, 'কাটার আগে পেঁয়াজ ফ্রিজে রাখলে চোখে পানি কম আসে কেন?', 'ঠান্ডায় ঝাঁঝালো গ্যাস কম ওড়ে', 'ফ্রিজে পেঁয়াজের রস শুকিয়ে যায়', 'ঠান্ডা পেঁয়াজ নরম হয়', 'ফ্রিজের গন্ধ ঝাঁঝ ঢেকে দেয়', 0, 'ঠান্ডায় রাসায়নিক বিক্রিয়া ধীর হয়, আর উদ্বায়ী গ্যাসও কম বাষ্প হয়ে ওড়ে — তাই চোখ পর্যন্ত কম পৌঁছায়।', NULL, NULL, NULL);
INSERT INTO quizzes (slug, kind, title, blurb, opens_at, seconds_per_question) VALUES ('series-mosha', 'initiator', 'রাফির কুইজ: মশার জীবন', 'ডেঙ্গুর মশা কখন কামড়ায়, কোথায় ডিম পাড়ে? রাফির সিরিজ থেকে ৫টি প্রশ্ন।', NULL, 20) ON DUPLICATE KEY UPDATE kind=VALUES(kind), title=VALUES(title), blurb=VALUES(blurb), opens_at=VALUES(opens_at), seconds_per_question=VALUES(seconds_per_question);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('init-mosha-1', 'series-mosha', 0, 'ডেঙ্গু ছড়ায় মূলত কোন মশা?', 'কিউলেক্স', 'অ্যানোফিলিস', 'এডিস', 'সব মশা সমানভাবে', 2, 'এডিস (Aedes) মশা ডেঙ্গু ছড়ায়। এর কালো শরীর আর পায়ে সাদা ডোরা দেখে চেনা যায়।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('init-mosha-2', 'series-mosha', 1, 'এডিস মশা সাধারণত কখন বেশি কামড়ায়?', 'দিনের বেলায়', 'শুধু মাঝরাতে', 'শুধু বৃষ্টির সময়', 'কখনোই কামড়ায় না', 0, 'এডিস মূলত দিনের বেলা কামড়ায়, বিশেষ করে সকালে আর বিকেলে। তাই দিনে ঘুমালেও মশারি ব্যবহার করা ভালো।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('init-mosha-3', 'series-mosha', 2, 'এডিস মশার ডিম পাড়ার জন্য কতটুকু পানি দরকার?', 'একটা পুকুর', 'অন্তত এক বালতি', 'এক চামচের মতো জমা পানিও যথেষ্ট', 'নদীর স্রোত', 2, 'ফুলের টব, বোতলের ঢাকনা বা টায়ারে জমা সামান্য পানিতেও এডিস ডিম পাড়ে। তাই কয়েক দিন পরপর জমা পানি ফেলে পাত্র ঘষে পরিষ্কার করো।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('init-mosha-4', 'series-mosha', 3, 'মশার গুনগুন শব্দ আসে কোথা থেকে?', 'মশার গলা থেকে', 'খুব দ্রুত ডানা ঝাপটানো থেকে', 'পায়ের ঘষা থেকে', 'শুঁড় নাড়ানো থেকে', 1, 'মশা সেকেন্ডে কয়েকশো বার ডানা ঝাপটায় — এই দ্রুত কম্পনই কানের কাছে তীক্ষ্ণ গুনগুন হয়ে বাজে।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('init-mosha-5', 'series-mosha', 4, 'মশার লার্ভা কোথায় বড় হয়?', 'শুকনো মাটিতে', 'গাছের পাতার নিচে', 'মানুষের চুলে', 'জমা পানিতে', 3, 'মশার ডিম ফুটে লার্ভা পানিতেই বড় হয়, মাঝে মাঝে ওপরে উঠে নলের মতো অঙ্গ দিয়ে শ্বাস নেয়। পানি না থাকলে মশার জীবনচক্রই আটকে যায়।', NULL, NULL, NULL);
INSERT INTO quizzes (slug, kind, title, blurb, opens_at, seconds_per_question) VALUES ('series-tara', 'initiator', 'মিমের কুইজ: তারার গল্প', 'শনির বলয়, চাঁদের একই মুখ আর সবচেয়ে কাছের তারা — মিমের সিরিজ থেকে ৫টি প্রশ্ন।', NULL, 20) ON DUPLICATE KEY UPDATE kind=VALUES(kind), title=VALUES(title), blurb=VALUES(blurb), opens_at=VALUES(opens_at), seconds_per_question=VALUES(seconds_per_question);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('init-tara-1', 'series-tara', 0, 'সৌরজগতের সবচেয়ে বড় গ্রহ কোনটি?', 'শনি', 'বৃহস্পতি', 'পৃথিবী', 'নেপচুন', 1, 'বৃহস্পতি এত বড় যে এর ভেতরে এক হাজারেরও বেশি পৃথিবী এঁটে যাবে।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('init-tara-2', 'series-tara', 1, 'শনির বলয় মূলত কী দিয়ে তৈরি?', 'গ্যাসের মেঘ', 'গলিত লোহা', 'বরফ আর পাথরের কণা', 'ধুলোর ঝড়', 2, 'বলয়ের বেশিরভাগটাই পানির বরফ — ধুলিকণার মতো ছোট থেকে বাড়ির সমান বড় টুকরো পর্যন্ত। এজন্যই বলয় এত ঝকঝকে।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('init-tara-3', 'series-tara', 2, 'চাঁদের একই মুখ সবসময় পৃথিবীর দিকে থাকে কেন?', 'নিজ অক্ষে ঘোরা আর পৃথিবী প্রদক্ষিণের সময় সমান বলে', 'চাঁদ একেবারেই ঘোরে না বলে', 'অন্য পাশটা মেঘে ঢাকা থাকে বলে', 'পৃথিবীর ছায়া অন্য পাশ ঢেকে রাখে বলে', 0, 'একে বলে টাইডাল লকিং (tidal locking)। কোটি কোটি বছর ধরে পৃথিবীর টানে চাঁদের ঘূর্ণন ধীর হয়ে এই তালে এসে থেমেছে।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('init-tara-4', 'series-tara', 3, 'অন্ধকার পরিষ্কার আকাশে খালি চোখে একসাথে মোটামুটি কতগুলো তারা দেখা যায়?', 'কয়েক ডজন', 'কয়েক হাজার', 'কয়েক লাখ', 'কয়েক কোটি', 1, 'অন্ধকার গ্রামের আকাশে একসাথে কয়েক হাজার তারা দেখা যায়। শহরের আলোয় সেটা কমে কয়েক ডজনে নেমে আসতে পারে।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('init-tara-5', 'series-tara', 4, 'সূর্যের পর পৃথিবীর সবচেয়ে কাছের তারা কোনটি?', 'ধ্রুবতারা', 'লুব্ধক (সিরিয়াস)', 'প্রক্সিমা সেন্টরি', 'শুকতারা', 2, 'প্রক্সিমা সেন্টরি (Proxima Centauri) প্রায় ৪.২ আলোকবর্ষ দূরে। মজার ব্যাপার, ‘শুকতারা’ আসলে তারাই নয় — শুক্র গ্রহ!', NULL, NULL, NULL);
INSERT INTO quizzes (slug, kind, title, blurb, opens_at, seconds_per_question) VALUES ('series-haor', 'initiator', 'তানভীরের কুইজ: হাওরের মাছ', 'কই কেন ডাঙায় হাঁটে, ইলিশ কেন নদীতে ফেরে — তানভীরের সিরিজ থেকে ৫টি প্রশ্ন।', NULL, 20) ON DUPLICATE KEY UPDATE kind=VALUES(kind), title=VALUES(title), blurb=VALUES(blurb), opens_at=VALUES(opens_at), seconds_per_question=VALUES(seconds_per_question);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('init-haor-1', 'series-haor', 0, 'কই মাছ পানির বাইরে কিছুক্ষণ বাঁচতে পারে কেন?', 'তার ফুসফুস আছে বলে', 'বাতাস থেকে শ্বাস নেওয়ার বাড়তি অঙ্গ আছে বলে', 'শরীরে পানি জমিয়ে রাখে বলে', 'আঁশ দিয়ে বাতাস শোষে বলে', 1, 'কইয়ের ফুলকার ওপরে গোলকধাঁধার মতো একটা অঙ্গ (labyrinth organ) আছে, যা দিয়ে সে সরাসরি বাতাস থেকে অক্সিজেন নিতে পারে।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('init-haor-2', 'series-haor', 1, 'কোন মাছ ডিম পাড়তে সাগর থেকে নদীতে আসে?', 'ইলিশ', 'রুই', 'শিং', 'পুঁটি', 0, 'ইলিশ সাগরে বড় হয়, কিন্তু ডিম পাড়তে উজান বেয়ে নদীর মিঠা পানিতে আসে। এমন মাছকে বলে অ্যানাড্রোমাস (anadromous) মাছ।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('init-haor-3', 'series-haor', 2, 'শুকনো মৌসুমে হাওরের পানি নেমে গেলে অনেক মাছ কোথায় আশ্রয় নেয়?', 'উঁচু জমির ধানক্ষেতে', 'বিলের গভীর অংশে আর নদীতে', 'গাছের গোড়ার গর্তে', 'সাগরে', 1, 'পানি নামলে মাছেরা বিলের গভীর অংশে আর আশপাশের নদীতে জড়ো হয়। তাই বিলে মাছের অভয়াশ্রম রাখা খুব জরুরি — পরের বর্ষার মাছ সেখান থেকেই আসে।', NULL, NULL, NULL);
