INSERT INTO quizzes (slug, kind, title, blurb, opens_at, seconds_per_question) VALUES ('druto-10', 'pool', 'দ্রুত ১০', 'প্রতি প্রশ্নে মাত্র ১০ সেকেন্ড! বড় প্রশ্নভান্ডার থেকে এলোমেলো ১০টা প্রশ্ন আসে — যত দ্রুত, তত মজা।', NULL, 10) ON DUPLICATE KEY UPDATE kind=VALUES(kind), title=VALUES(title), blurb=VALUES(blurb), opens_at=VALUES(opens_at), seconds_per_question=VALUES(seconds_per_question);
