INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('pool-21', 'druto-10', 20, 'আলো আর শব্দের মধ্যে কে বেশি দ্রুত?', 'শব্দ', 'আলো', 'দুটোই সমান', 'আবহাওয়ার ওপর নির্ভর করে', 1, 'আলো সেকেন্ডে প্রায় ৩ লাখ কিলোমিটার যায়, শব্দ বাতাসে মাত্র প্রায় ৩৪৩ মিটার। তাই আগে বিদ্যুৎ চমকায়, পরে গর্জন।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('pool-22', 'druto-10', 21, 'খাবার লবণের রাসায়নিক নাম কী?', 'সোডিয়াম ক্লোরাইড', 'ক্যালসিয়াম কার্বোনেট', 'পটাশিয়াম নাইট্রেট', 'সোডিয়াম বাইকার্বোনেট', 0, 'সোডিয়াম ক্লোরাইড (NaCl)। আয়োডিনযুক্ত লবণ খেলে গলগণ্ডের ঝুঁকি কমে।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('pool-23', 'druto-10', 22, 'কোন পাখি মাথা প্রায় পেছনে ঘোরাতে পারে?', 'মুরগি', 'চড়ুই', 'পেঁচা', 'বক', 2, 'পেঁচা ঘাড় প্রায় ২৭০ ডিগ্রি ঘোরাতে পারে। চোখ নড়াতে পারে না বলে পুরো মাথা ঘুরিয়েই দেখে।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('pool-24', 'druto-10', 23, 'পদ্মা সেতুর মূল অংশ প্রায় কত লম্বা?', 'প্রায় ২ কিমি', 'প্রায় ৬ কিমি', 'প্রায় ১২ কিমি', 'প্রায় ২০ কিমি', 1, 'মূল সেতু প্রায় ৬.১৫ কিলোমিটার লম্বা — খরস্রোতা পদ্মার ওপর এটা ছিল প্রকৌশলের বড় চ্যালেঞ্জ।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('pool-25', 'druto-10', 24, 'অ্যান্টিবায়োটিক কোন জীবাণু মারে?', 'ভাইরাস', 'দুটোই', 'কোনোটিই না', 'ব্যাকটেরিয়া', 3, 'অ্যান্টিবায়োটিক কাজ করে ব্যাকটেরিয়ার বিরুদ্ধে, সর্দি-জ্বরের ভাইরাসের বিরুদ্ধে নয়। ডাক্তারের পরামর্শ ছাড়া খাওয়া ঝুঁকিপূর্ণ।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('pool-26', 'druto-10', 25, '২০০৬ সালে প্লুটোকে কী ঘোষণা করা হয়?', 'নতুন গ্রহ', 'ধূমকেতু', 'উপগ্রহ', 'বামন গ্রহ', 3, 'আন্তর্জাতিক জ্যোতির্বিজ্ঞান ইউনিয়ন ২০০৬ সালে প্লুটোকে ‘বামন গ্রহ’ (dwarf planet) শ্রেণিতে সরায়।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('pool-27', 'druto-10', 26, 'শরীরের সবচেয়ে ছোট হাড় কোথায়?', 'কানে', 'আঙুলে', 'নাকে', 'পায়ে', 0, 'মধ্যকর্ণের স্টেপিস (stapes) হাড় চালের দানার চেয়েও ছোট — অথচ এটা ছাড়া আমরা ঠিকমতো শুনতে পেতাম না।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('pool-28', 'druto-10', 27, 'আঙুলের ছাপ শ্রেণিবিন্যাসে অবদান রাখা বাঙালি কে?', 'জামাল নজরুল ইসলাম', 'প্রফুল্লচন্দ্র রায়', 'কাজী আজিজুল হক', 'মেঘনাদ সাহা', 2, 'কাজী আজিজুল হক আঙুলের ছাপ শ্রেণিবিন্যাসের গাণিতিক পদ্ধতি তৈরিতে মূল ভূমিকা রাখেন — যা ‘হেনরি পদ্ধতি’ নামে পরিচিত হয়।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('pool-29', 'druto-10', 28, 'স্থলের সবচেয়ে দ্রুতগামী প্রাণী কোনটি?', 'চিতা', 'সিংহ', 'ঘোড়া', 'হরিণ', 0, 'চিতা অল্প দূরত্বে ঘণ্টায় প্রায় ১০০ কিলোমিটার বেগে ছুটতে পারে — তবে বেশিক্ষণ নয়।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('pool-30', 'druto-10', 29, 'লজ্জাবতী ছুঁলে পাতা গুটায় কেন?', 'ভয় পায় বলে', 'বাতাসের ধাক্কায়', 'পাতার গোড়ার কোষ থেকে পানি সরে যায় বলে', 'রোদ কমে যায় বলে', 2, 'ছোঁয়া পেলে পাতার গোড়ার কোষ থেকে পানি দ্রুত বেরিয়ে যায়, কোষ চুপসে পাতা ভাঁজ হয়ে যায়।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('pool-31', 'druto-10', 30, 'ঘুমিয়ে পড়ার মুহূর্তে হঠাৎ ঝাঁকুনির নাম কী?', 'হেঁচকি', 'খিঁচুনি', 'দুঃস্বপ্ন', 'হিপনিক জার্ক', 3, 'ঘুমের শুরুতে পেশির এই হঠাৎ ঝাঁকুনি খুবই সাধারণ — বেশিরভাগ মানুষেরই কখনো না কখনো হয়।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('pool-32', 'druto-10', 31, 'কোন গ্যাস বাড়লে পৃথিবী বেশি গরম হয়?', 'কার্বন ডাই-অক্সাইড', 'অক্সিজেন', 'নাইট্রোজেন', 'আর্গন', 0, 'কার্বন ডাই-অক্সাইড তাপ আটকে রাখে। কয়লা-তেল-গ্যাস পোড়ালে এর পরিমাণ বাড়ে, পৃথিবীও গরম হয়।', NULL, NULL, NULL);
INSERT INTO quizzes (slug, kind, title, blurb, opens_at, seconds_per_question) VALUES ('bhabu-secret', 'secret', 'ভাবুর গোপন কুইজ 🤫', 'তুমি ভাবুকে খুঁজে পেয়েছ! পাঁচটা মজার প্রশ্ন, প্রতিটায় ১৫ সেকেন্ড — আর কাউকে বোলো না।', NULL, 15) ON DUPLICATE KEY UPDATE kind=VALUES(kind), title=VALUES(title), blurb=VALUES(blurb), opens_at=VALUES(opens_at), seconds_per_question=VALUES(seconds_per_question);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('secret-1', 'bhabu-secret', 0, '‘ভাবা যায়!’ নামের শেষের ‘!’ চিহ্নটার নাম কী?', 'প্রশ্নবোধক চিহ্ন', 'বিস্ময়সূচক চিহ্ন', 'কোলন', 'হাইফেন', 1, 'বিস্ময়সূচক চিহ্ন! ভাবু মনে করে, প্রতিটা ভালো প্রশ্নের শেষে একটা ‘!’ লুকিয়ে থাকে — উত্তর জানার পরের অবাক হওয়াটা।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('secret-2', 'bhabu-secret', 1, 'অক্টোপাসের কয়টি হৃৎপিণ্ড?', '১', '২', '৩', '৮', 2, 'তিনটি! দুটি ফুলকায় রক্ত পাঠায়, একটি বাকি শরীরে। আর তার রক্ত নীল — তামা-ভিত্তিক হিমোসায়ানিনের (hemocyanin) কারণে।', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('secret-3', 'bhabu-secret', 2, 'জেলিফিশের মগজ কয়টি?', 'একটিও নেই', 'একটি', 'দুটি', 'আটটি', 0, 'জেলিফিশের কোনো মগজ নেই — শরীরজুড়ে ছড়ানো স্নায়ুর জাল দিয়েই সে চলে। ভাবুর চেয়ে অনেক কম ভাবে, তবু কোটি কোটি বছর ধরে টিকে আছে!', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('secret-4', 'bhabu-secret', 3, 'কৌতূহল জাগলে মস্তিষ্কে কী ঘটে বলে গবেষণায় দেখা গেছে?', 'মাথাব্যথা হয়', 'ঘুম পায়', 'কিছুই হয় না', 'শেখা জিনিস মনে রাখা সহজ হয়', 3, 'কিছু গবেষণায় দেখা গেছে, কৌতূহল জাগলে মস্তিষ্কের পুরস্কার-ব্যবস্থা সক্রিয় হয়, আর তখন শেখা তথ্য মনে রাখাও সহজ হয়। প্রশ্ন করাটাই তাই সেরা পড়ার কৌশল!', NULL, NULL, NULL);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('secret-5', 'bhabu-secret', 4, 'অন্যকে হাই তুলতে দেখে নিজেরও হাই ওঠাকে কী বলে?', 'ঘুমের ডাক', 'ছোঁয়াচে হাই', 'আলসেমি রোগ', 'ক্লান্তির ঢেউ', 1, 'এটা ‘ছোঁয়াচে হাই’ (contagious yawning)। হাই নিয়ে পড়লেও অনেকের হাই ওঠে — এই লাইন পড়তে পড়তে উঠল নাকি?', NULL, NULL, NULL);
INSERT INTO quizzes (slug, kind, title, blurb, opens_at, seconds_per_question) VALUES ('bhabu-quiz-s1', 'season', 'ভাবু কুইজ · সিজন ১', 'ফেসবুকের সাপ্তাহিক ভাবু কুইজের আসল ১৩টি প্রশ্ন — অক্টোপাস থেকে সাগরের অক্সিজেন।', NULL, 20) ON DUPLICATE KEY UPDATE kind=VALUES(kind), title=VALUES(title), blurb=VALUES(blurb), opens_at=VALUES(opens_at), seconds_per_question=VALUES(seconds_per_question);
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('p41-01', 'bhabu-quiz-s1', 0, 'অক্টোপাসের হৃৎপিণ্ড কয়টি?', '১টি', '২টি', '৩টি', '৮টি', 2, 'একটি পুরো শরীরে রক্ত পাঠায়। বাকি দুটি রক্ত পাঠায় ফুলকায়, অক্সিজেন নিতে। রক্ত নীল: তামাভিত্তিক হিমোসায়ানিন। তাই বাড়তি চাপে পাম্প লাগে। জানতেন? সাঁতারের সময় মূল হৃৎপিণ্ড থেমে যায়, তাই অক্টোপাস হামাগুড়ি দিতেই পছন্দ করে।', '/media/quiz/p41/q01-octopus.webp', 'ভাবু কুইজ সপ্তাহ ০১: অক্টোপাসের হৃৎপিণ্ড কয়টি?', 'Diego Delso, Wikimedia Commons, CC BY-SA 4.0');
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('p41-02', 'bhabu-quiz-s1', 1, 'কোন গ্রহে একদিন এক বছরের চেয়ে লম্বা?', 'মঙ্গল', 'শুক্র', 'বৃহস্পতি', 'বুধ', 1, 'নিজের অক্ষে একবার ঘুরতে লাগে প্রায় ২৪৩ দিন। সূর্যকে একবার ঘুরে আসে মাত্র প্রায় ২২৫ দিনে। ঘোরে উল্টো দিকে, তাই ওখানে সূর্য ওঠে পশ্চিমে! জানতেন? মানে শুক্রে এক ''দিন'' শেষ হওয়ার আগেই জন্মদিন চলে আসে।', '/media/quiz/p41/q02-venus.webp', 'ভাবু কুইজ সপ্তাহ ০২: কোন গ্রহে একদিন এক বছরের চেয়ে লম্বা?', 'NASA, Wikimedia Commons, সর্বজনীন সম্পত্তি');
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('p41-03', 'bhabu-quiz-s1', 2, 'কোন স্থলপ্রাণীর চোখ সবচেয়ে বড়?', 'হাতি', 'জিরাফ', 'উটপাখি', 'ঘোড়া', 2, 'একেকটি চোখের ব্যাস প্রায় ৫ সেন্টিমিটার। একটা টেবিল টেনিস বলের চেয়েও বড়। ডাঙার সব মেরুদণ্ডী প্রাণীর মধ্যে এটাই সবচেয়ে বড় চোখ। জানতেন? হাতি শরীরে বিশাল, কিন্তু চোখে উটপাখির কাছে হার!', '/media/quiz/p41/q03-ostrich.webp', 'ভাবু কুইজ সপ্তাহ ০৩: কোন স্থলপ্রাণীর চোখ সবচেয়ে বড়?', 'William Warby, Wikimedia Commons, CC BY 2.0');
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('p41-04', 'bhabu-quiz-s1', 3, 'কোন পাখি পেছন দিকে উড়তে পারে?', 'চড়ুই', 'হামিংবার্ড', 'ঈগল', 'পেঙ্গুইন', 1, 'কাঁধে আছে বল-সকেট জয়েন্ট, পাখিদের মধ্যে যা বিরল। ডানা ঘুরিয়ে বাতাসে আটের মতো (∞) পথ আঁকে। সামনে-পেছনে দুই টানেই ঠেলা তৈরি হয়, তাই পেছনেও যেতে পারে। জানতেন? ছোট প্রজাতির হামিংবার্ড সেকেন্ডে প্রায় ৯৯ বার ডানা ঝাপটায়।', '/media/quiz/p41/q04-hummingbird.webp', 'ভাবু কুইজ সপ্তাহ ০৪: কোন পাখি পেছন দিকে উড়তে পারে?', 'Charles J. Sharp, Wikimedia Commons, CC BY-SA 4.0');
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('p41-05', 'bhabu-quiz-s1', 4, 'কিছু বাঁশ একদিনে সর্বোচ্চ কতটা বাড়ে?', '১ সেমি', '১০ সেমি', 'প্রায় ৯১ সেমি', '৫ মিটার', 2, 'মানে ঘণ্টায় প্রায় ৪ সেন্টিমিটার। গিনেস রেকর্ডে এটাই দ্রুততম বর্ধনশীল উদ্ভিদ। জাপানের এক প্রজাতিতে একদিনে ১২০ সেমিও দেখা গেছে। জানতেন? মন দিয়ে দেখলে প্রায় চোখের সামনেই বাঁশ বাড়ছে!', '/media/quiz/p41/q05-bamboo.webp', 'ভাবু কুইজ সপ্তাহ ০৫: কিছু বাঁশ একদিনে সর্বোচ্চ কতটা বাড়ে?', 'D-Kuru, Wikimedia Commons, CC BY-SA 4.0');
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('p41-06', 'bhabu-quiz-s1', 5, 'সূর্যের আলো পৃথিবীতে আসতে কত সময় লাগে?', '৮ সেকেন্ড', 'প্রায় ৮ মিনিট', '৮ ঘণ্টা', '৮ দিন', 1, 'সূর্য আমাদের থেকে প্রায় ১৫ কোটি কিলোমিটার দূরে। আলো এই পথ পেরোয় গড়ে ৮ মিনিট ২০ সেকেন্ডে। তাই আকাশে যে সূর্য দেখেন, সেটা ৮ মিনিট আগের ছবি। জানতেন? সূর্যের দিকে কখনো খালি চোখে তাকাবেন না।', '/media/quiz/p41/q06-sunlight.webp', 'ভাবু কুইজ সপ্তাহ ০৬: সূর্যের আলো পৃথিবীতে আসতে কত সময় লাগে?', 'NASA/SDO (AIA), Wikimedia Commons, সর্বজনীন সম্পত্তি');
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('p41-07', 'bhabu-quiz-s1', 6, 'উদ্ভিদবিজ্ঞানে কোনটি আসল বেরি?', 'স্ট্রবেরি', 'কলা', 'আপেল', 'আম', 1, 'বেরি হয় একটি ফুলের একটি গর্ভাশয় থেকে, বীজ থাকে শাঁসের ভেতরে। কলা এই শর্ত মেলে, তাই কলা আসল বেরি। স্ট্রবেরির লাল অংশ ফুলের আধার; বাইরের দানাগুলোই আসল ফল। জানতেন? নামে ''বেরি'' থাকলেই বেরি নয়, এই প্রশ্নে অনেকেই ধরা খান!', '/media/quiz/p41/q07-banana.webp', 'ভাবু কুইজ সপ্তাহ ০৭: উদ্ভিদবিজ্ঞানে কোনটি আসল বেরি?', 'Wilfredor, Wikimedia Commons, CC0');
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('p41-08', 'bhabu-quiz-s1', 7, 'দুটি বাঘের ডোরা কি হুবহু এক?', 'হ্যাঁ, সবার এক', 'ভাইবোনের এক', 'না, প্রত্যেকের আলাদা', 'শুধু বাঘিনীর আলাদা', 2, 'প্রতিটি বাঘের ডোরার নকশা অনন্য। গবেষকরা ডোরা দেখেই বনে আলাদা আলাদা বাঘ চেনেন। ঠিক আমাদের আঙুলের ছাপের মতো। জানতেন? আমাদের রয়েল বেঙ্গল টাইগারও এর ব্যতিক্রম নয়।', '/media/quiz/p41/q08-tiger-stripes.webp', 'ভাবু কুইজ সপ্তাহ ০৮: দুটি বাঘের ডোরা কি হুবহু এক?', 'Charles J. Sharp, Wikimedia Commons, CC BY-SA 4.0');
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('p41-09', 'bhabu-quiz-s1', 8, 'কোন ধাতু হাতের তালুতেই গলে যায়?', 'লোহা', 'তামা', 'গ্যালিয়াম', 'অ্যালুমিনিয়াম', 2, 'গ্যালিয়াম গলে প্রায় ২৯.৭৬° সেলসিয়াসে। আমাদের শরীরের তাপমাত্রা প্রায় ৩৭° সেলসিয়াস। তাই হাতে রাখলে কঠিন ধাতু ধীরে তরল হয়ে যায়। জানতেন? ল্যাবের বাইরে কোনো ধাতু খালি হাতে নেড়েচেড়ে দেখবেন না।', '/media/quiz/p41/q09-gallium.webp', 'ভাবু কুইজ সপ্তাহ ০৯: কোন ধাতু হাতের তালুতেই গলে যায়?', 'Maxim Bilovitskiy, Wikimedia Commons, CC BY-SA 4.0');
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('p41-10', 'bhabu-quiz-s1', 9, 'জোনাকি আসলে কী?', 'মাছি', 'গুবরে পোকা', 'মথ', 'মশা', 1, 'জোনাকি ল্যাম্পিরিডি পরিবারের বিটল। পেটের কোষে লুসিফেরিন আর অক্সিজেন মিলে আলো জ্বলে। এই আলোতে প্রায় কোনো তাপ নেই, তাই বলে ''ঠান্ডা আলো''। জানতেন? নামে ''ফায়ারফ্লাই'', কিন্তু মাছিও নয়, আগুনও নয়!', '/media/quiz/p41/q10-firefly.webp', 'ভাবু কুইজ সপ্তাহ ১০: জোনাকি আসলে কী?', 'Sumanth699, Wikimedia Commons, CC BY 4.0');
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('p41-11', 'bhabu-quiz-s1', 10, 'পানি কোন তাপমাত্রায় সবচেয়ে ঘন?', '০° সে.', 'প্রায় ৪° সে.', '৫০° সে.', '১০০° সে.', 1, 'প্রায় ৪° সে.-এ পানির ঘনত্ব সবচেয়ে বেশি। বরফ পানির চেয়ে প্রায় ৯% কম ঘন, তাই ভাসে। তাই হ্রদ জমে ওপর থেকে, নিচের পানিতে মাছ বেঁচে থাকে। জানতেন? বেশির ভাগ তরল ঠান্ডায় শুধু ঘন হয়, পানি এখানে ব্যতিক্রম।', '/media/quiz/p41/q11-water-4c.webp', 'ভাবু কুইজ সপ্তাহ ১১: পানি কোন তাপমাত্রায় সবচেয়ে ঘন?', 'Joli Rumi, Wikimedia Commons, CC BY-SA 4.0');
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('p41-12', 'bhabu-quiz-s1', 11, 'শব্দ কোনটার ভেতর দিয়ে সবচেয়ে দ্রুত চলে?', 'বাতাস', 'পানি', 'ইস্পাত', 'শূন্যস্থান', 2, 'বাতাসে শব্দ চলে সেকেন্ডে প্রায় ৩৪৩ মিটার। পানিতে প্রায় ১৪৮১, ইস্পাতে প্রায় ৫৯০০ মিটার। শূন্যস্থানে কোনো মাধ্যম নেই, তাই শব্দ চলেই না। জানতেন? রেললাইনে কান পেতে পরীক্ষা করবেন না, বিপদ!', '/media/quiz/p41/q12-sound-speed.webp', 'ভাবু কুইজ সপ্তাহ ১২: শব্দ কোনটার ভেতর দিয়ে সবচেয়ে দ্রুত চলে?', 'Sabbir Bin Shahjahan, Wikimedia Commons, CC BY-SA 4.0');
INSERT INTO quiz_questions (id, quiz_slug, position, question, option_a, option_b, option_c, option_d, answer, fact, image, image_alt, credit) VALUES ('p41-13', 'bhabu-quiz-s1', 12, 'অর্ধেক অক্সিজেন কোথা থেকে আসে?', 'আমাজন বন', 'সাগরের প্ল্যাংকটন', 'সুন্দরবন', 'মরুর ক্যাকটাস', 1, 'NOAA বলছে, পৃথিবীর প্রায় অর্ধেক অক্সিজেন আসে সাগর থেকে। মূল কারিগর ক্ষুদ্র ফাইটোপ্ল্যাংকটন, খালি চোখে প্রায় অদৃশ্য। সাগরের প্রাণীরা আবার প্রায় সমান অক্সিজেন খরচও করে। জানতেন? ছবির সবুজ ঘূর্ণি আসলে কোটি কোটি প্ল্যাংকটন, মহাকাশ থেকে তোলা।', '/media/quiz/p41/q13-ocean-oxygen.webp', 'ভাবু কুইজ সপ্তাহ ১৩: অর্ধেক অক্সিজেন কোথা থেকে আসে?', 'NASA Earth Observatory images by Wanmei , Wikimedia Commons, সর্বজনীন সম্পত্তি');
